import { sql } from 'drizzle-orm';
import { check, integer, sqliteTable, text } from 'drizzle-orm/sqlite-core';

export const projectRuntime = sqliteTable(
  'project_runtime',
  {
    singleton: integer().primaryKey(),
    pid: integer().notNull(),
    token: text().notNull(),
    phase: text({ enum: ['active', 'starting', 'retiring'] }).notNull(),
  },
  (table) => [
    check('project_runtime_singleton', sql`${table.singleton} = 1`),
    check('project_runtime_pid', sql`${table.pid} > 0`),
    check(
      'project_runtime_phase',
      sql`${table.phase} IN ('active', 'starting', 'retiring')`,
    ),
  ],
);
